            continue
        # ensure mid-range difficulty
        if not (0.15 * total_pairs <= count <= 0.85 * total_pairs):
            continue
        assign = {
            'p': p,
            'q': q,
            'r': r,
            'p_str': f"{p:.4f}",
            'q_str': f"{q:.4f}",
            'r_str': f"{r:.4f}",
            'a': int(a),
