            'n_max': int(n_max),
            'm_max': int(m_max),
            'lam': lam,
            'lam_str': f"{lam:.4f}",
        }
        return assign
    # If all tries fail, fall back to a deterministic valid instance
    p = 0.72
    r = 0.12
    q = 1 - p - r
    a = 4
    b = 6
    n_max = 20
    m_max = 20
    lam = 0.90
    return {
        'p': p,
        'q': q,
        'r': r,
        'p_str': f"{p:.4f}",
        'q_str': f"{q:.4f}",
        'r_str': f"{r:.4f}",
        'a': a,
        'b': b,
        'n_max': n_max,
        'm_max': m_max,
